def calculate_R(N):
    """Calculates R(N) = sum_{a=1}^N sum_{b=1}^N {ab / (N+1)}"""
    R_N = 0.0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Calculate the fractional part: {x} = x - floor(x)
            fractional_part = (a * b) / (N + 1) - (a * b) // (N + 1)
            R_N += fractional_part
    return R_N

def target_T(N):
    """Calculates the target value T(N) = (N^3 - N^2 + 2) / 4"""
    return (N**3 - N**2 + 2) / 4

