def S(N):
    """Calculates S(N) = sum_{a=1}^N sum_{b=1}^N floor(ab / (N+1))"""
    sum_val = 0
    M = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            sum_val += (a * b) // M
    return sum_val

def Target_T_prime(N):
    """Calculates the target value T'(N) = (N^2 - 1) / 2 as specified in the task."""
    return (N**2 - 1) / 2

